def apply(inputs, premises):
    spans = inputs.get('source_spans', [])
    answers = inputs.get('semantic_answers', [])
    seen = set()
    for answer in answers:
        if isinstance(answer, dict) and isinstance(answer.get('id'), str):
            seen.add(answer.get('id'))
    queries = []
    all_ids = []
    for span in spans:
        if isinstance(span, dict) and 'id' in span and isinstance(span.get('text'), str):
            all_ids.append(span.get('id'))
    for span in spans:
        if not isinstance(span, dict) or 'id' not in span or not isinstance(span.get('text'), str):
            continue
        unit_id = span.get('id')
        low = span.get('text').lower()
        disclosure = ('disclos' in low or 'restrict access' in low or 'make accessible' in low) and ('employee' in low or 'director' in low or 'officer' in low or 'contractor' in low or 'affiliate' in low or 'third party' in low or 'third-party' in low or 'advisor' in low or 'adviser' in low or 'consultant' in low or 'agent' in low)
        if disclosure:
            for operation in ('disclosure_modality', 'disclosure_recipient_scope', 'disclosure_conditions'):
                query_id = operation + '|unit|' + str(unit_id)
                if query_id not in seen:
                    queries.append({'id': query_id, 'operation': operation, 'unit_ids': [unit_id]})
        disposal = ('return' in low or 'destroy' in low) and ('confidential information' in low or 'document' in low or 'material' in low or 'copies' in low or 'copy' in low)
        if disposal:
            for operation in ('disposal_action', 'disposal_trigger', 'retention_effect'):
                query_id = operation + '|unit|' + str(unit_id)
                if query_id not in seen:
                    queries.append({'id': query_id, 'operation': operation, 'unit_ids': [unit_id]})
    if all_ids:
        anchor = ','.join(str(value) for value in all_ids)
        for operation in ('scan_disclosure_permission', 'scan_disposal_obligation', 'scan_retention_effect'):
            query_id = operation + '|all|' + anchor
            if query_id not in seen:
                queries.append({'id': query_id, 'operation': operation, 'unit_ids': list(all_ids)})
    return {'queries': queries}
